"use strict";
// Async generators the island owns: each next() answers an island promise the
// program's `for await` must adopt, and leaving the loop closes the generator.
exports.ticks = async function* (limit) {
  for (let i = 1; i <= limit; i++) {
    await Promise.resolve();
    console.log("island", i);
    yield i;
  }
};
exports.ticked = async function* (limit) {
  try {
    for (let i = 0; i < limit; i++) yield i;
  } finally {
    console.log("closed");
  }
};
exports.rejects = async function* () {
  yield 1;
  throw new Error("async-boom");
};
exports.naturals = function* (limit) {
  for (let i = 0; i < limit; i++) yield i;
};
